import { useContext, useState } from "react";
import { AppContext } from "../context/AppContext";

export default function LoginPage() {
  const { setRole, setUsername } = useContext(AppContext);
  const [role, setLocalRole] = useState("user");
  const [username, setUser] = useState("");
  const [password, setPass] = useState("");

  function submit(e) {
    e.preventDefault();

    if (role === "admin") {
      if (username === "admin" && password === "admin") {
        setRole("admin");
      } else {
        alert("Invalid admin credentials");
      }
    } else {
      setUsername(username);
      setRole("user");
    }
  }

  return (
    <section className="card">
      <div className="card-header">
        <div>
          <h2>Login</h2>
          <p>Select role and enter credentials</p>
        </div>
      </div>

      <div className="role-select">
        <label className="chip">
          <input type="radio" checked={role === "user"} onChange={() => setLocalRole("user")} />
          User
        </label>
        <label className="chip">
          <input type="radio" checked={role === "admin"} onChange={() => setLocalRole("admin")} />
          Admin
        </label>
      </div>

      <form className="login-form" onSubmit={submit}>
        <input placeholder="User ID" onChange={e => setUser(e.target.value)} />
        <input type="password" placeholder="Password" onChange={e => setPass(e.target.value)} />
        <button className="btn btn-primary">Login</button>
      </form>
    </section>
  );
}
